from pathlib import Path
import json,copy
ROOT=Path(__file__).resolve().parents[3]
def read(p):return json.loads((ROOT/p).read_text())
def write(p,d):
 f=ROOT/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def item(title,text,ids=None):return dict(title=title,text=text,source_ids=ids or ['nccp','smpc'])
def chapter(id,title,intro,items):return dict(id=id,title=title,intro=intro,items=items)
def source(id,title,url):return dict(id=id,title=title,url=url)
def row(label,cells):return dict(label=label,cells=cells,source_ids=['nccp'])
