d.update(context_label='Metastatic colorectal cancer after standard therapies and trifluridine/tipiracil or regorafenib',purpose='Fruquintinib is a targeted capsule treatment to help control bowel cancer that has spread after previous treatments. The team checks which treatments you have received, whether they remain suitable, and your priorities.',indication_text='NCCP 00890a: metastatic colorectal cancer after available standard therapies, with progression on or intolerance to trifluridine/tipiracil or regorafenib.',scope_heading='Previously treated colorectal cancer',scope_note='The team confirms the full treatment history, including chemotherapy, anti-VEGF and anti-EGFR treatment where applicable, and progression or intolerance on trifluridine/tipiracil or regorafenib.',treatment_scope_notice='Previously treated metastatic colorectal cancer; follow the individual prescription and monitoring plan.',cycle_days=28,cycle_display='28-day cycle',service_kind='targeted',therapy_label='Oral targeted therapy',schedule_kind='cyclic_oral_21_on_7_off',schedule_label='21 days of capsules, then seven days without capsules',phases_title='Capsules and rest days',phases_note='No fixed final cycle. Continue only while benefit and tolerability justify treatment.',medicines_title='Your targeted medicine')
schedule='Take the prescribed fruquintinib dose once daily on Days 1–21, then take no fruquintinib on Days 22–28. Take it at about the same time each day, with or without food. Repeat only when your team authorises the next cycle.'
missed='If a dose is less than 12 hours late, take it and then follow the usual schedule. If more than 12 hours late, skip it and take the next dose at the normal time. At exactly 12 hours, or if unsure, ask your pharmacist or team. Do not take a replacement capsule after vomiting; take the next dose at the usual time.'
d.update(schedule_summary=schedule,administration_text='The usual starting dose is 5 mg once daily, but follow your own label. Swallow capsules whole with water, with or without food; do not chew, dissolve or open them. Tell the team before starting if swallowing capsules is difficult.',passport_visit_note='Record the prescribed dose, treatment days, rest days, blood-pressure readings and tests. A diary entry is not permission to restart after a hold.',urgent_extra='Get urgent help for severe or persistent tummy pain, black or bloody stools, coughing or vomiting blood, new severe headache, confusion, seizure, visual change, chest pain, sudden breathlessness or very little urine. Report fever, sudden illness, painful hands/feet and new bleeding promptly.')
d['agents']=[dict(id='fruquintinib',name='Fruquintinib',alias='Fruzaqla',type='Targeted therapy capsule',mechanism='Blocks VEGF receptor signals',explanation='Fruquintinib blocks VEGF receptor signals that help tumours form blood vessels. Reducing these signals can slow cancer growth. Blood vessels in healthy tissues are also affected, which helps explain blood-pressure, bleeding, protein-in-urine and wound-healing risks.',visual=['VEGF signals','Receptors blocked','Blood-vessel growth reduced'],watch='Report painful hands/feet, bowel changes, bleeding or neurological symptoms; attend blood-pressure, urine and blood checks even if well.',source_ids=['smpc'],risks=['High blood pressure, including severe hypertension','Painful red hands and feet','Protein in urine and kidney complications','Bleeding, bowel perforation, clotting and impaired wound healing','Thyroid changes, liver-test abnormalities, diarrhoea, fatigue, appetite/weight loss and mouth soreness','Rare serious neurological or blood-vessel complications'],symptoms=['Hand-foot skin reaction','Diarrhoea','Mouth soreness / ulcers','Fatigue'])]
d['anatomy']=[['brain','Head / thyroid / energy','Fruquintinib','Fatigue and thyroid changes can affect daily life. Severe headache, confusion, seizure or visual change needs emergency help.',50,5],['mouth','Mouth / appetite','Fruquintinib','Mouth soreness, voice change and poor appetite can affect eating. Report difficulty drinking or weight loss.',50,12.5],['heart','Heart / blood pressure','Fruquintinib','Blood pressure may rise without symptoms. Keep scheduled checks. Chest pain, collapse or severe breathlessness needs emergency care.',52.5,28.3],['blood','Blood / bleeding','Fruquintinib','New bleeding, easy bruising, fever or sudden illness needs prompt advice. Heavy bleeding needs emergency help.',40,22],['liver','Liver','Fruquintinib','Liver tests can change before symptoms occur. Report yellow eyes or skin, dark urine or persistent abdominal pain.',44,34],['bowel','Bowel / abdomen','Fruquintinib','Diarrhoea can cause dehydration. Severe persistent pain, black stools or blood in stools needs urgent help.',50,44],['hands','Hands / feet / skin','Fruquintinib','Pain, redness, swelling or blisters can affect walking or using your hands. Report early and follow the skin-care plan.',31,57],['kidneys','Kidneys / urine','Fruquintinib','Protein in urine may have no early symptoms. Attend urine checks and report swelling or much less urine.',62,39]]
