d['support']=[item('Skin care','Use the unit’s skin-care plan and report redness, pain, swelling or blisters early. The team may prescribe creams or change treatment. Do not wait until walking or everyday hand use is difficult.'),item('Sickness and bowels','This oral medicine has minimal-to-low emetogenic potential. Routine premedication is not usually needed; agree any anti-sickness and diarrhoea medicines with the team. Persistent vomiting, diarrhoea, poor intake or reduced urine needs prompt advice.', ['nccp']),item('Blood pressure and medication review','Take prescribed blood-pressure medicines and keep monitoring visits. Tell the team about anticoagulants and every prescription, over-the-counter and herbal medicine.'),item('Pregnancy and breastfeeding','Use highly effective contraception during treatment and for at least two weeks after the last dose if you could become pregnant. Do not breastfeed during treatment or for at least two weeks afterwards.', ['nccp','smpc'])]
d['consent_support']='Discuss the previously treated colorectal setting, benefit and uncertainty, alternatives, blood-pressure and urine monitoring, hand-foot effects, fatigue, mouth/bowel/appetite effects, serious bleeding, clotting, bowel perforation and neurological risks, wound healing, pregnancy precautions, medicine interactions and the option to reconsider.'
d['evidence']=dict(title='Evidence in previously treated colorectal cancer',intro='FRESCO-2 compared fruquintinib plus best supportive care with placebo plus best supportive care after previous metastatic colorectal treatments.',population='Previously treated metastatic colorectal cancer; participants had received or could not tolerate trifluridine/tipiracil, regorafenib, or both.',metrics=[],interpretation='Median overall survival was 7.4 months with fruquintinib and 4.8 months with placebo. These group medians are not a prediction of one person’s lifespan or a guaranteed extra 2.6 months. The team should discuss the balance of benefit and side effects for you.',limitations='The result applies to the trial population and treatment setting. It does not mean all patients benefit or that earlier-line treatments are interchangeable.',source_ids=['fresco2','smpc'])
d['chapters']=[chapter('understanding','Why this treatment may be offered','Confirm the treatment history and personal goals.',[item('Previously treated bowel cancer',d['purpose']+' '+d['scope_note']),item('Evidence and uncertainty',d['evidence']['interpretation'],['fresco2']),item('Treatment duration','There is no fixed total number of cycles. Continue while benefit and tolerability justify it; the team reviews symptoms, scans, tests and your preferences.')]),chapter('medicine','How fruquintinib works','It affects signals involved in blood-vessel growth.',[item('VEGF receptor signals',d['agents'][0]['explanation']),item('Safety checks','Blood-pressure and urine-protein changes can develop without symptoms. Tests and early symptom reporting help the team decide whether treatment can safely continue.')]),chapter('capsules','Your capsule and rest-day plan','Use your own prescription and calendar.',[item('Days 1–21 and Days 22–28',schedule),item('Swallow whole, with or without food',d['administration_text']),item('Missed or vomited dose',missed),item('If too much is taken','Contact your doctor immediately if you take more than prescribed. You may need medical attention; take the pack and treatment calendar with you.')]),chapter('testing','Checks and follow-up','Feeling well does not replace testing.',[item('Before and during treatment',d['monitoring_summary']),item('If a test is abnormal','The team may arrange extra blood or urine tests, treat hypertension, pause capsules, reduce the dose or stop treatment. Do not change the dose yourself.'),item('Scans and tumour markers','The consultant decides the imaging and marker schedule for your situation. This regimen does not mandate a fixed CT or CEA interval.'),item('After a pause or stopping','Ask who follows persistent symptoms and abnormal tests, and when the next review is due. Do not restart without clear instructions.')]),chapter('daily-life','Skin, mouth, eating and energy','Early support can help preserve daily activities.',[item('Hands and feet',d['support'][0]['text']),item('Bowels, fluids and sickness',d['support'][1]['text']),item('Mouth and appetite','Report mouth soreness, voice changes, poor appetite or weight loss. Ask for mouth care and nutritional support. Drink as advised for your health.'),item('Fatigue and thyroid','New marked fatigue, feeling unusually cold, weight or skin changes may need thyroid assessment. Balance activity with rest and report symptoms affecting usual activities.'),item('Driving','Do not drive or use machinery if tiredness or other symptoms affect concentration or reactions.', ['smpc'])]),chapter('urgent','Symptoms needing urgent help','A rare effect may still need immediate care.',[item('Bleeding and bowel problems','Seek urgent help for black or bloody stools, blood in urine, coughing/vomiting blood, severe or persistent abdominal pain. Heavy bleeding or collapse needs emergency care.'),item('Neurological, heart or vascular symptoms','Severe headache with confusion, seizure or visual changes, chest pain, severe breathlessness, sudden weakness or sudden severe chest/back/abdominal pain requires emergency help.'),item('Kidneys, skin and infection','Report much less urine or swelling, painful hands/feet, fever, shivering or suddenly feeling unwell. Symptoms may need assessment even during the capsule-free week.')]),chapter('procedures','Other medicines, wounds and procedures','Tell every treating team you take fruquintinib.',[item('Medication review','Tell the pharmacist about anticoagulants, antibiotics, infection treatments, seizure medicines, herbal remedies and supplements. Rifampicin and other strong enzyme inducers can affect fruquintinib exposure. Ask before starting or stopping anything.', ['smpc']),item('Wound healing and surgery','Report unhealed wounds and planned surgery. Product information recommends withholding fruquintinib for at least two weeks before surgery and not restarting for at least two weeks afterwards and until adequate wound healing. Your oncology and surgical teams must agree the exact plan; do not stop or restart it yourself.', ['smpc']),item('Allergies','Tell the pharmacist about medicine or colouring-agent allergies. Capsule colours differ by strength and contain colouring agents that can cause allergic reactions.', ['smpc'])]),chapter('pregnancy-storage','Pregnancy precautions and safe storage','Keep the medicine in its labelled packaging.',[item('Pregnancy and feeding',d['support'][3]['text']),item('Storage','Keep the original bottle tightly closed to protect from moisture and out of children’s sight and reach. No special temperature conditions are required. Follow the expiry date and ask the pharmacist how to return unused capsules; do not put them into household waste or wastewater.', ['smpc']),item('Your treatment record','Carry the wallet card and current medicine list. Record the prescribed dose, any holds, symptoms, BP and upcoming tests. Replace all example telephone numbers with your real oncology contacts before using the card.')])]
